using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging.Abstractions;
using MKSANCrud.Data;
using MKSANCrud.Models;
using MKSANCrud.Services.Clinica;
using MKSANCrud.Services.Database;
using MKSANCrud.Services.Agendamento;
internal static class JornadaPostgresChecks {
 public static async Task RunAsync(Action<bool,string> check){var connection=Environment.GetEnvironmentVariable("CALLMED_TEST_DB")??throw new Exception("Local test database required");var cs=new Npgsql.NpgsqlConnectionStringBuilder(connection);if(cs.Host!="127.0.0.1"||!cs.Database!.StartsWith("callmed_test"))throw new Exception("Only isolated local test databases are accepted");MKSANContext Db()=>new(new DbContextOptionsBuilder<MKSANContext>().UseNpgsql(connection).Options);var clock=new ClinicaClock();
 await using(var db=Db()){await db.Database.EnsureDeletedAsync();await db.Database.EnsureCreatedAsync();foreach(var table in new[]{"RespostasClinicas","Jornadas","Ofertas","ChavesClinicas","FormulariosClinicos","SinaisTele","LinksConsulta","MobileTickets","MedicoesOperacionais","PepEventos","Salas"})await PgTestDdl.ExecuteAsync(db,"DROP TABLE IF EXISTS \"",table,"\" CASCADE");await db.Database.ExecuteSqlRawAsync("ALTER TABLE \"ListasEspera\" DROP COLUMN IF EXISTS \"Prioridade\"");await db.Database.ExecuteSqlRawAsync("ALTER TABLE \"Consultas\" DROP COLUMN IF EXISTS \"Revisao\"");await new DatabaseSchemaV31Initializer(db).AplicarAsync();await new DatabaseSchemaV31Initializer(db).AplicarAsync();await new DatabaseSchemaV32Initializer(db).AplicarAsync();await new DatabaseSchemaV36Initializer(db).AplicarAsync();check(await db.Jornadas.CountAsync()==0&&await db.Ofertas.CountAsync()==0&&await db.PepEventos.CountAsync()==0,"V31 cria tabelas no PostgreSQL e permite reaplicação");db.Users.Add(new Usuario{Id="fixture",UserName="fixture@ficticio.invalid"});db.Pacientes.AddRange(new Paciente{Id=1,Nome="Fictício A",Cpf="52998224725"},new Paciente{Id=2,Nome="Fictício B",Cpf="11144477735"});db.Especialidades.Add(new(){Id=1,Nome="Clínica geral"});db.Medicos.AddRange(new Medico{Id=1,Nome="Fictício M",EspecialidadeId=1},new Medico{Id=2,Nome="Fictício N",EspecialidadeId=1});db.Salas.Add(new(){Id=1,Nome="Sala teste"});foreach(var h in new[]{"10:00","10:15","11:00"})db.Disponibilidades.Add(new(){MedicoId=1,Data=clock.Hoje.AddDays(1),Horario=h,Ativo=true});await db.SaveChangesAsync();}
 AgendamentoService Agenda(MKSANContext db){var conv=new ConvenioService(clock);return new(db,clock,new(db),conv,new(db,conv),NullLogger<AgendamentoService>.Instance);}async Task<ResultadoOperacaoConsulta> Book(int pid,string hour,Guid? offer=null){await using var db=Db();return await Agenda(db).AgendarAsync(pid,1,clock.Hoje.AddDays(1),hour,null,ct:default,ofertaId:offer);}
 var raced=await Task.WhenAll(Book(1,"10:00"),Book(2,"10:00"));check(raced.Count(x=>x.Sucesso)==1,"Agendamentos concorrentes ocupam um único horário");int otherId;await using(var db=Db()){var c=new Consulta{PacienteId=2,MedicoId=2,Data=clock.Hoje.AddDays(1),Horario="10:15",Status=ConsultaStatus.Confirmada};db.Consultas.Add(c);await db.SaveChangesAsync();otherId=c.Id;}
 async Task<string?> Room(int id){await using var db=Db();var j=new JornadaService(db,clock);var c=await db.Consultas.SingleAsync(x=>x.Id==id);return await j.AlocarAsync(c,JornadaChecks.User("fixture","Funcionario"),1,30,false,default);}
 var winner=raced.Single(x=>x.Sucesso).Consulta!.Id;var rooms=await Task.WhenAll(Room(winner),Room(otherId));check(rooms.Count(x=>x==null)==1,"Reserva concorrente de sala rejeita intervalos sobrepostos");Guid oid;
 await using(var db=Db()){var l=new ListaEspera{PacienteId=1,MedicoId=1,Ativa=true};db.ListasEspera.Add(l);await db.SaveChangesAsync();var o=new Oferta{ListaEsperaId=l.Id,MedicoId=1,Data=clock.Hoje.AddDays(1),Horario="11:00",ExpiraEm=DateTime.UtcNow.AddMinutes(10)};db.Ofertas.Add(o);await db.SaveChangesAsync();oid=o.Id;}
 var accepts=await Task.WhenAll(Book(1,"11:00",oid),Book(2,"11:00"));check(accepts[0].Sucesso&&!accepts[1].Sucesso,"Reserva de encaixe vence disputa com agendamento comum");await using(var db=Db()){check(await db.Consultas.CountAsync(x=>x.MedicoId==1&&x.Horario=="11:00")==1&&await db.Ofertas.AnyAsync(x=>x.Id==oid&&x.Estado=="Aceita"&&x.ConsultaId!=null),"Aceite persiste consulta e oferta consumida na transação PostgreSQL");}
 await using(var db=Db()) {
  var day=clock.Hoje.AddDays(2);db.Disponibilidades.AddRange(new(){MedicoId=1,Data=day,Horario="13:00",Ativo=true},new(){MedicoId=1,Data=day,Horario="13:50",Ativo=true});db.ListasEspera.AddRange(new(){PacienteId=1,MedicoId=1,DataPreferida=day,Periodo="Tarde",Ativa=true},new(){PacienteId=2,MedicoId=1,DataPreferida=day,Periodo="Tarde",Ativa=true,Prioridade=5});await db.SaveChangesAsync();
  var conv=new ConvenioService(clock);var envio=new MKSANCrud.Services.Atendimento.AtendimentoEnvioService([],db,TimeProvider.System,NullLogger<MKSANCrud.Services.Atendimento.AtendimentoEnvioService>.Instance,Microsoft.Extensions.Options.Options.Create(new MKSANCrud.Options.GmailInboxOptions()));
  var motor=new EncaixeService(db,clock,new(db,conv),new(db,new(db)),envio,new Microsoft.Extensions.Configuration.ConfigurationBuilder().Build());
  check(await motor.ReservarAsync()==2,"Motor de encaixe executa filtros e reservas no PostgreSQL real");
  var offers=await db.Ofertas.Include(o=>o.ListaEspera).Where(o=>o.Estado=="Aberta"&&o.Data==day).ToListAsync();check(offers.Select(o=>o.ListaEspera.PacienteId).Distinct().Count()==2&&offers.Single(o=>o.Horario=="13:00").ListaEspera.PacienteId==2,"Prioridade e reserva única por candidato funcionam no banco real");
 }

 }
}
